using System.Collections.Generic;
using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "BlessedPathRunModifier", menuName = "Data/RunModifiers/BlessedPathRunModifier", order = 0)]
public class BlessedPathRunModifier : RunModifier
{
	[Header("Specifics")]
	[SerializeField]
	private OmenReward starBlessingReward;

	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.BlessedPathRunModifier = this;
	}

	public Reward[] GetBattleModifiedRewards(Reward[] nonModifiedRewards)
	{
		List<Reward> list = nonModifiedRewards.DuplicateAsList();
		list.Add(starBlessingReward);
		return list.ToArray();
	}
}
